#!/usr/bin/env python3
import os
import json
import math
import re
from functools import cmp_to_key

# Element symbol to atomic number mapping
ELEMENT_Z = {
    'H': 1, 'He': 2, 'Li': 3, 'Be': 4, 'B': 5, 'C': 6, 'N': 7, 'O': 8, 'F': 9, 'Ne': 10,
    'Na': 11, 'Mg': 12, 'Al': 13, 'Si': 14, 'P': 15, 'S': 16, 'Cl': 17, 'Ar': 18,
    'K': 19, 'Ca': 20, 'Sc': 21, 'Ti': 22, 'V': 23, 'Cr': 24, 'Mn': 25, 'Fe': 26, 'Co': 27, 'Ni': 28, 'Cu': 29, 'Zn': 30,
    'Ga': 31, 'Ge': 32, 'As': 33, 'Se': 34, 'Br': 35, 'Kr': 36,
    'Rb': 37, 'Sr': 38, 'Y': 39, 'Zr': 40, 'Nb': 41, 'Mo': 42, 'Tc': 43, 'Ru': 44, 'Rh': 45, 'Pd': 46, 'Ag': 47, 'Cd': 48,
    'In': 49, 'Sn': 50, 'Sb': 51, 'Te': 52, 'I': 53, 'Xe': 54,
    'Cs': 55, 'Ba': 56, 'La': 57, 'Ce': 58, 'Pr': 59, 'Nd': 60, 'Pm': 61, 'Sm': 62, 'Eu': 63, 'Gd': 64, 'Tb': 65, 'Dy': 66,
    'Ho': 67, 'Er': 68, 'Tm': 69, 'Yb': 70, 'Lu': 71, 'Hf': 72, 'Ta': 73, 'W': 74, 'Re': 75, 'Os': 76, 'Ir': 77, 'Pt': 78, 'Au': 79, 'Hg': 80,
    'Tl': 81, 'Pb': 82, 'Bi': 83, 'Po': 84, 'At': 85, 'Rn': 86,
    'Fr': 87, 'Ra': 88, 'Ac': 89, 'Th': 90, 'Pa': 91, 'U': 92, 'Np': 93, 'Pu': 94, 'Am': 95, 'Cm': 96, 'Bk': 97, 'Cf': 98, 'Es': 99, 'Fm': 100,
}

def find_xs_files(base_path):
    files = []
    if not os.path.exists(base_path):
        return files
    for root, dirs, filenames in os.walk(base_path):
        for filename in filenames:
            if filename.endswith('.xs'):
                full_path = os.path.join(root, filename)
                files.append(full_path)
    return files

def get_depth(full_path, base_path):
    rel_path = os.path.relpath(full_path, base_path)
    parts = rel_path.split(os.sep)
    return len(parts) - 1

def parse_xs_file(filepath):
    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except Exception:
        return None

    lines = content.splitlines()
    isotopes = []
    current_isotope_name = None
    current_isotope_points = []

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('ISOTOPE:'):
            if current_isotope_name is not None:
                isotopes.append({'name': current_isotope_name, 'points': current_isotope_points})
                current_isotope_points = []
            current_isotope_name = line.split(':', 1)[1]
        elif line.startswith('ENERGY:'):
            if current_isotope_name is not None:
                rest = line.split(':', 1)[1]
                parts = rest.split()
                data_point = {}
                for p in parts:
                    if p.startswith('ENERGY:'):
                        data_point['energy'] = float(p.split(':')[1])
                    elif p.startswith('SIGMA_T:'):
                        data_point['sigma_t'] = float(p.split(':')[1])
                    elif p.startswith('SIGMA_A:'):
                        data_point['sigma_a'] = float(p.split(':')[1])
                    elif p.startswith('SIGMA_S:'):
                        data_point['sigma_s'] = float(p.split(':')[1])
                if 'energy' in data_point:
                    current_isotope_points.append(data_point)
    if current_isotope_name is not None:
        isotopes.append({'name': current_isotope_name, 'points': current_isotope_points})
    return isotopes

def load_atomic_densities(filepath):
    densities = {}
    if not os.path.exists(filepath):
        return densities
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split(':')
            if len(parts) >= 3:
                isotope_key = parts[0]
                density = float(parts[1])
                mass = float(parts[2])
                densities[isotope_key] = {'density': density, 'mass': mass}
    return densities

def normalize_name(name):
    return name.lower().replace(' ', '').replace('-', '')

def is_valid_isotope_name(name):
    return any(c.isdigit() for c in name)

def parse_isotope_name_to_z_a(name):
    """Extract Z and A from isotope name."""
    # Find mass number (digits) - assume it's at the end
    # Use regex to find all digit sequences
    matches = re.findall(r'\d+', name)
    if not matches:
        return None, None  # Can't determine A
    # Take the last match as mass number A
    mass_str = matches[-1]
    try:
        A = int(mass_str)
    except:
        return None, None

    # Everything before the last digit group is the element part
    last_match_idx = len(name) - len(matches[-1])
    # Actually need to find position of the last digits
    last_match = re.search(r'\d+$', name)
    if not last_match:
        # No digits at end - can't parse properly
        return None, None
    element_part = name[:last_match.start()].strip()

    # Now try to find Z from element_part
    # element_part could be "U", "U-235" without the number already removed, etc.
    # But we removed the number part, so element_part is before the number
    elem_str = element_part.strip()
    # Check if it's a symbol
    elem_upper = elem_str.upper()
    if elem_upper in ELEMENT_Z:
        Z = ELEMENT_Z[elem_upper]
        return Z, A
    # Maybe it's full element name like "uranium"
    # Check if any element symbol is contained in elem_str or vice versa
    found = False
    for symbol, z in ELEMENT_Z.items():
        if symbol.lower() in elem_str.lower() or elem_str.lower() in symbol.lower():
            # Prefer symbol if it matches exactly
            if symbol == elem_str or symbol.lower() == elem_str.lower():
                Z = z
                return Z, A
    # If still can't find Z, return None for Z (will use 0 fallback)
    return None, A  # Will handle None Z in sorting

def find_density_match(isotope_name, densities_dict):
    if isotope_name in densities_dict:
        return densities_dict[isotope_name]
    for key in densities_dict:
        if key.lower() == isotope_name.lower():
            return densities_dict[key]
    norm_name = normalize_name(isotope_name)
    for key in densities_dict:
        if normalize_name(key) == norm_name:
            return densities_dict[key]
    return None

def compare_files(f1, f2):
    d1 = get_depth(f1, "/app/data/cross_sections")
    d2 = get_depth(f2, "/app/data/cross_sections")
    if d1 != d2:
        if d1 > d2:
            return -1
        elif d1 < d2:
            return 1
    if f1 > f2:
        return -1
    elif f1 < f2:
        return 1
    return 0

def compare_isotopes(e1, e2):
    name1 = e1['isotope']
    name2 = e2['isotope']
    z1, a1 = parse_isotope_name_to_z_a(name1)
    z2, a2 = parse_isotope_name_to_z_a(name2)
    if z1 is None: z1 = 0
    if z2 is None: z2 = 0
    if a1 is None: a1 = 0
    if a2 is None: a2 = 0
    if z1 > z2:
        return -1
    elif z1 < z2:
        return 1
    if a1 > a2:
        return -1
    elif a1 < a2:
        return 1
    if name1 > name2:
        return -1
    elif name1 < name2:
        return 1
    return 0

def main():
    base_path = "/app/data/cross_sections"
    xs_files = find_xs_files(base_path)

    xs_files.sort(key=cmp_to_key(compare_files))

    density_path = "/app/data/atomic_densities.txt"
    densities_file = load_atomic_densities(density_path)

    seen_isotopes = {}  # normalized_name -> first source_file
    results = []
    total_files = 0
    valid_files = 0
    invalid_files = 0

    for full_path in xs_files:
        total_files += 1
        rel_path = os.path.relpath(full_path, base_path)
        isotopes_data = parse_xs_file(full_path)

        if isotopes_data is None:
            invalid_files += 1
            continue

        if not isotopes_data:  # no ISOTOPE lines ever encountered
            invalid_files += 1
            continue

        valid_files += 1

        for iso in isotopes_data:
            isotope_name = iso['name']
            points = iso['points']
            source_file = rel_path

            norm_name = normalize_name(isotope_name)
            is_duplicate = norm_name in seen_isotopes

            validation_errors = []
            if not is_valid_isotope_name(isotope_name):
                validation_errors.append("invalid_isotope_name")

            has_mismatch = False
            for pt in points:
                if abs(pt['sigma_t'] - (pt['sigma_a'] + pt['sigma_s'])) > 0.001:
                    has_mismatch = True
                    break
            if has_mismatch:
                validation_errors.append("cross_section_mismatch")

            energies = [pt['energy'] for pt in points]
            if energies[0] <= 0:
                validation_errors.append("invalid_energy_ordering")
            for i in range(1, len(energies)):
                if energies[i] <= energies[i-1]:
                    validation_errors.append("invalid_energy_ordering")
                    break

            has_negative = False
            for pt in points:
                if pt['sigma_t'] < 0 or pt['sigma_a'] < 0 or pt['sigma_s'] < 0:
                    has_negative = True
                    break
            if has_negative:
                validation_errors.append("negative_cross_section")

            for pt in points:
                if math.isnan(pt['energy']) or math.isinf(pt['energy']):
                    validation_errors.append("invalid_format")
                if math.isnan(pt['sigma_t']) or math.isinf(pt['sigma_t']):
                    validation_errors.append("invalid_format")
                if math.isnan(pt['sigma_a']) or math.isinf(pt['sigma_a']):
                    validation_errors.append("invalid_format")
                if math.isnan(pt['sigma_s']) or math.isinf(pt['sigma_s']):
                    validation_errors.append("invalid_format")

            validation_errors.sort()

            # Find thermal cross-section
            thermal_xs_barns_val = None
            best_dist = None
            best_energy = None
            found_within = False
            for pt in points:
                dist = abs(pt['energy'] - 0.025)
                if dist <= 0.1:
                    found_within = True
                    if best_dist is None or dist < best_dist:
                        best_dist = dist
                        best_energy = pt['energy']
                        thermal_xs_barns_val = pt['sigma_t']
                    elif dist == best_dist:
                        if pt['energy'] > best_energy:
                            best_dist = dist
                            best_energy = pt['energy']
                            thermal_xs_barns_val = pt['sigma_t']

            # Determine status
            status = None
            has_invalid_format = "invalid_format" in validation_errors
            has_cross_section = "cross_section_mismatch" in validation_errors
            has_energy = "invalid_energy_ordering" in validation_errors
            has_negative = "negative_cross_section" in validation_errors
            has_invalid_name = "invalid_isotope_name" in validation_errors

            if has_invalid_format:
                status = "invalid_format"
            elif has_cross_section:
                status = "cross_section_mismatch"
            elif has_energy:
                status = "invalid_energy_ordering"
            elif has_negative:
                status = "negative_cross_section"
            elif has_invalid_name:
                status = "invalid_isotope_name"
            else:
                if is_duplicate:
                    status = "duplicate_isotope"
                else:
                    density_info = find_density_match(isotope_name, densities_file)
                    if density_info is None:
                        status = "missing_density_data"
                    else:
                        if not found_within:
                            status = "insufficient_data"
                        else:
                            status = "valid"

            # Calculate values
            atomic_density_atoms_cm3 = None
            macroscopic_xs_rounded = None
            reaction_rate_rounded = None
            thermal_xs_barns_out = None

            density_info = find_density_match(isotope_name, densities_file)
            if density_info and found_within:
                density = density_info['density']
                mass = density_info['mass']
                N = (density / mass) * 6.02214076e23  # unrounded N
                macroscopic_xs_unrounded = N * (thermal_xs_barns_val * 1e-24)
                macroscopic_xs_rounded = round(macroscopic_xs_unrounded, 6)
                reaction_rate = 1e14 * macroscopic_xs_rounded
                reaction_rate_rounded = round(reaction_rate, 6)
                atomic_density_atoms_cm3_out = round(N, 6)
                thermal_xs_barns_out = thermal_xs_barns_val
            else:
                atomic_density_atoms_cm3_out = None
                macroscopic_xs_rounded = None
                reaction_rate_rounded = None
                thermal_xs_barns_out = None

            results.append({
                "isotope": isotope_name,
                "source_file": source_file,
                "status": status,
                "atomic_density_atoms_cm3": atomic_density_atoms_cm3_out,
                "macroscopic_cross_section_cm_minus1": macroscopic_xs_rounded,
                "reaction_rate_reactions_cm3_s": reaction_rate_rounded,
                "thermal_xs_barns": thermal_xs_barns_out,
                "validation_errors": validation_errors
            })

            if not is_duplicate:
                seen_isotopes[norm_name] = source_file

    # Sort results for output
    results.sort(key=cmp_to_key(compare_isotopes))

    output = {
        "total_files": total_files,
        "valid_files": valid_files,
        "invalid_files": invalid_files,
        "total_isotopes": len(results),
        "valid_isotopes": sum(1 for r in results if r['status'] == 'valid'),
        "invalid_isotopes": sum(1 for r in results if r['status'] != 'valid'),
        "isotopes": results
    }

    tmp_path = "/app/cross_section_report.json.tmp"
    with open(tmp_path, 'w') as f:
        json.dump(output, f)
    os.rename(tmp_path, "/app/cross_section_report.json")

if __name__ == "__main__":
    main()
